const cmds = [
  ["status", "rtk git status --short --branch"],
  ["files", "rtk fd -H -d 3 '^(Cargo.toml|justfile|\\.github|\\.moon|moon\\.yml|CHANGELOG|README|release)' ."],
  ["entire_help", "rtk entire search --help"],
  ["history_release", "rtk entire search --json --compact 'date:>=2026-09-09 release self-release publish crates.io tag CI'"],
  ["history_claude", "rtk entire search --json --compact 'date:>=2026-09-09 author:claude release failure fix PR'"]
];
const results = await Promise.all(cmds.map(async ([name, cmd]) => {
  const x = await tools.exec_command({cmd, workdir:"/Users/gabe/Projects/callisto", yield_time_ms:30000, max_output_tokens:12000});
  return {name, ...x};
}));
for (const x of results) {
  text(`## ${x.name}\n${x.output}\n(exit ${x.exit_code ?? "running"})`);
}

const ids = ["34698997105","34702634375","34719001370","34702602426","34673588882"];
const results = await Promise.all(ids.map(async id => {
  const x = await tools.exec_command({
    cmd:`rtk gh run view ${id} --json databaseId,name,event,status,conclusion,createdAt,updatedAt,headBranch,headSha,url,jobs`,
    workdir:"/Users/gabe/Projects/callisto", yield_time_ms:30000, max_output_tokens:18000,
    sandbox_permissions:"require_escalated", justification:"May I inspect the details and job outcomes of the suspect release/CI runs read-only?", prefix_rule:["gh","run","view"]
  });
  return {id, output:x.output, exit:x.exit_code};
}));
for (const x of results) text(`## RUN ${x.id}\n${x.output}\n(exit ${x.exit})`);

