    assert_eq!(
        req,
        set(&["npmMainPackages", "npmPlatformPackages", "releases", "rustCrates", "schemaVersion"])
    );
    assert_eq!(
        props,
        set(&[
            "diagnostics", "npmMainPackages", "npmPlatformPackages", "pypiPackages", "releases",
