  1 //! Pure reconciliation of a durable release execution state.
  2 //!
  3 //! This is deliberately separate from the executor: it observes neither Git,
  4 //! registries, nor a forge. Its only authority is one exact intent and the
  5 //! state explicitly bound to that intent.
  6 
  7 use std::collections::{BTreeMap, BTreeSet};
  8 
  9 use callisto_model::{
 10     ApplyPermit, ArtifactManifestV1, OperationState, ReleaseExecutionStateV1, ReleaseIntentV1, ReleaseOperationId,
 11 };
 12 
 13 use crate::{
 14     commands::{ReleaseStateStore, ReleaseStateWriter},
 15     GraphError,
 16 };
 17 
 18 use super::release::ValidatedReleaseIntent;
 19 use crate::error::ReleasePreconditionRequirement;
 20 
 21 /// Executes eligible operations one at a time with crash-safe state updates.
 22 ///
 23 /// `Attempting` is persisted before dispatch. If dispatch returns an error,
 24 /// the state deliberately remains `Attempting`: recovery must observe the
 25 /// exact remote identity rather than guessing whether an effect occurred.
 26 pub fn execute_release<W: ReleaseStateWriter>(
 27     capability: &ValidatedReleaseIntent<'_>,
 28     store: &ReleaseStateStore<W>,
 29     permit: &ApplyPermit,
 30 ) -> Result<ReleaseExecutionStateV1, GraphError> {
 31     execute_release_with_artifacts(capability, store, permit, None)
 32 }
 33 
 34 /// Executes a release after requiring the exact artifact manifest whenever
 35 /// the intent declares compiled-binary slots.
 36 pub fn execute_release_with_artifacts<W: ReleaseStateWriter>(
 37     capability: &ValidatedReleaseIntent<'_>,
 38     store: &ReleaseStateStore<W>,
 39     permit: &ApplyPermit,
 40     artifacts: Option<&ArtifactManifestV1>,
 41 ) -> Result<ReleaseExecutionStateV1, GraphError> {
 42     let intent = capability.intent();
 43     require_artifact_manifest_matches_intent(intent, artifacts)?;
 44     let mut state = store.load_or_initialize(intent, permit)?;
 45     loop {
 46         let Some(operation) = reconcile_release_execution(intent, &state)?.eligible().first().cloned() else {
 47             break;
 48         };
 49         capability.recheck_trust()?;
 50         state
 51             .mark_attempting(&operation)
 52             .map_err(|source| GraphError::ReleaseExecutionState { source })?;
 53         store.save(intent, &state, permit)?;
 54 
 55         let outcome = capability.dispatch_prepared(permit, &operation)?;
 56         state
 57             .mark_terminal(&operation, outcome)
 58             .map_err(|source| GraphError::ReleaseExecutionState { source })?;
 59         store.save(intent, &state, permit)?;
 60     }
 61     Ok(state)
 62 }
 63 
 64 /// Requires an exact artifact manifest whenever `intent` declares
 65 /// compiled-binary artifact slots, and that a provided manifest actually
 66 /// validates against `intent` when one is supplied regardless of slot
 67 /// count (a manifest supplied for a slot-less intent must still be a real,
 68 /// intent-bound manifest, not silently ignored).
 69 fn require_artifact_manifest_matches_intent(
 70     intent: &ReleaseIntentV1,
 71     artifacts: Option<&ArtifactManifestV1>,
 72 ) -> Result<(), GraphError> {
 73     match (intent.artifact_slots.is_empty(), artifacts) {
 74         (true, None) => Ok(()),
 75         (true, Some(manifest)) | (false, Some(manifest)) => manifest
 76             .validate_for_intent(intent)
 77             .map_err(|source| GraphError::ArtifactManifest { source }),
 78         (false, None) => Err(GraphError::ReleasePreconditionUnmet {
 79             requirement: ReleasePreconditionRequirement::ArtifactManifestProvided,
 80         }),
 81     }
 82 }
 83 
 84 /// The exact pending operations which are safe for a future executor to
 85 /// consider. Being listed here does not perform an effect or bypass its
 86 /// immediately-before-effect revalidation.
 87 #[derive(Clone, Debug, PartialEq, Eq)]
 88 pub struct ReconciledReleaseExecution {
 89     eligible: Vec<ReleaseOperationId>,
 90 }
 91 
 92 impl ReconciledReleaseExecution {
 93     /// Operations in the intent's stable canonical order.
 94     pub fn eligible(&self) -> &[ReleaseOperationId] {
 95         &self.eligible
 96     }
 97 }
 98 
 99 /// Reconciles `state` against exactly `intent` without performing any I/O.
100 ///
101 /// An operation is eligible only while it is `Pending` and every *transitive*
102 /// prerequisite is exactly `Published` or `AlreadySatisfied`. `Attempting`,
103 /// missing, failed, and blocked operations are never inferred as success.
104 pub fn reconcile_release_execution(
105     intent: &ReleaseIntentV1,
106     state: &ReleaseExecutionStateV1,
107 ) -> Result<ReconciledReleaseExecution, GraphError> {
108     state
109         .validate_for_intent(intent)
110         .map_err(|source| GraphError::ReleaseExecutionState { source })?;
111 
112     let prerequisites: BTreeMap<_, _> = intent
113         .operations
114         .iter()
115         .map(|operation| (operation.id().clone(), operation.prerequisites().to_vec()))
116         .collect();
117 
118     let mut eligible = Vec::new();
119     for operation in &intent.operations {
120         if state.operation_state(operation.id()) != Some(OperationState::Pending) {
121             continue;
122         }
123         let mut visited = BTreeSet::new();
124         if prerequisites_satisfied_transitively(operation.id(), &prerequisites, state, &mut visited) {
125             eligible.push(operation.id().clone());
126         }
127     }
128     Ok(ReconciledReleaseExecution { eligible })
129 }
130 
131 fn prerequisites_satisfied_transitively(
132     id: &ReleaseOperationId,
133     prerequisites: &BTreeMap<ReleaseOperationId, Vec<ReleaseOperationId>>,
134     state: &ReleaseExecutionStateV1,
135     visited: &mut BTreeSet<ReleaseOperationId>,
136 ) -> bool {
137     // `ReleaseIntentV1` has already proved this is a DAG. Keeping the visited
138     // guard makes this helper fail closed if a future model version violates
139     // that invariant rather than recursing indefinitely.
140     if !visited.insert(id.clone()) {
141         return false;
142     }
143     let result = prerequisites.get(id).is_some_and(|direct| {
144         direct.iter().all(|prerequisite| {
145             matches!(
146                 state.operation_state(prerequisite),
147                 Some(OperationState::Published | OperationState::AlreadySatisfied)
148             ) && prerequisites_satisfied_transitively(prerequisite, prerequisites, state, visited)
149         })
150     });
151     visited.remove(id);
152     result
153 }
