142     // GitHub Actions checks out the merge commit detached.  Git-commit trust
143     // deliberately requires that topology, rather than accepting a mutable
144     // branch ref as release authority.
145     git(root, &["checkout", "--detach", &release_commit]);
146     (dir, release_commit)
