 182 fn read_intent(path: &std::path::Path) -> Result<ReleaseIntentV1, CliError> {
 183     serde_json::from_value(read_json_file(path)?)
 184         .map_err(|error| CliError::Other(format!("invalid release intent {}: {error}", path.display())))
 185 }
 186 
 187 fn read_artifact_manifest(path: &std::path::Path) -> Result<ArtifactManifestV1, CliError> {
 188     serde_json::from_value(read_json_file(path)?)
 189         .map_err(|error| CliError::Other(format!("invalid artifact manifest {}: {error}", path.display())))
 190 }
 191 
 192 fn read_json_file(path: &std::path::Path) -> Result<serde_json::Value, CliError> {
 193     let content = std::fs::read_to_string(path).map_err(|source| CliError::Io {
 194         source,
 195         path: Some(path.to_path_buf()),
 196     })?;
 197     serde_json::from_str(&content)
 198         .map_err(|error| CliError::Other(format!("invalid JSON in {}: {error}", path.display())))
 199 }
