 201 fn write_intent(path: &std::path::Path, intent: &ReleaseIntentV1, permit: &ApplyPermit) -> Result<(), CliError> {
 202     let content = serde_json::to_string_pretty(intent).expect("release intent serializes") + "\n";
 203     callisto_model::atomic::atomic_write(path, &content, permit).map_err(|source| CliError::Io {
 204         source,
 205         path: Some(path.to_path_buf()),
 206     })?;
 207     Ok(())
 208 }

