  64 /// Requires an exact artifact manifest whenever `intent` declares
  65 /// compiled-binary artifact slots, and that a provided manifest actually
  66 /// validates against `intent` when one is supplied regardless of slot
  67 /// count (a manifest supplied for a slot-less intent must still be a real,
  68 /// intent-bound manifest, not silently ignored).
  69 fn require_artifact_manifest_matches_intent(
  70     intent: &ReleaseIntentV1,
  71     artifacts: Option<&ArtifactManifestV1>,
  72 ) -> Result<(), GraphError> {
  73     match (intent.artifact_slots.is_empty(), artifacts) {
  74         (true, None) => Ok(()),
  75         (true, Some(manifest)) | (false, Some(manifest)) => manifest
  76             .validate_for_intent(intent)
  77             .map_err(|source| GraphError::ArtifactManifest { source }),
  78         (false, None) => Err(GraphError::ReleasePreconditionUnmet {
  79             requirement: ReleasePreconditionRequirement::ArtifactManifestProvided,
  80         }),
  81     }
  82 }
