1778     pub fn mark_attempting(&mut self, id: &ReleaseOperationId) -> Result<(), ReleaseStateError> {
1779         let state = self
1780             .operations
1781             .get_mut(id)
1782             .ok_or_else(|| ReleaseStateError::UnknownOperation {
1783                 id: Box::new(id.clone()),
1784             })?;
1785         if *state != OperationState::Pending {
1786             return Err(ReleaseStateError::InvalidTransition {
1787                 id: Box::new(id.clone()),
1788                 from: *state,
1789             });
1790         }
1791         *state = OperationState::Attempting;
1792         Ok(())
1793     }
