1900     /// Constructs a receipt only when state is complete and exact for `intent`.
1901     pub fn from_state(intent: &ReleaseIntentV1, state: &ReleaseExecutionStateV1) -> Result<Self, ReleaseReceiptError> {
1902         state
1903             .validate_for_intent(intent)
1904             .map_err(ReleaseReceiptError::InvalidState)?;
1905         let mut outcomes = BTreeMap::new();
1906         for (id, operation_state) in &state.operations {
1907             let outcome = match operation_state {
1908                 OperationState::Published => OperationOutcome::Published,
1909                 OperationState::AlreadySatisfied => OperationOutcome::AlreadySatisfied,
1910                 OperationState::Failed | OperationState::Blocked { .. } => {
1911                     return Err(ReleaseReceiptError::NonSuccessfulOperation {
1912                         id: Box::new(id.clone()),
1913                     });
1914                 }
1915                 OperationState::Pending | OperationState::Attempting => {
1916                     return Err(ReleaseReceiptError::NonTerminalOperation {
1917                         id: Box::new(id.clone()),
1918                     });
1919                 }
1920             };
1921             outcomes.insert(id.clone(), outcome);
1922         }
1923         Ok(Self {
1924             schema_version: Self::SCHEMA_VERSION,
1925             intent_digest: state.intent_digest.clone(),
1926             outcomes,
1927         })
1928     }
