1333 /// Maps a `url::ParseError` to a specific, static diagnostic reason for
1334 /// [`GraphError::UnsafeRegistryBinding`]/[`GraphError::UnsafeGitRemote`],
1335 /// rather than discarding it behind one generic "invalid URL" message.
1336 fn url_parse_error_reason(error: url::ParseError) -> &'static str {
1337     match error {
1338         url::ParseError::RelativeUrlWithoutBase => "URL has no scheme (e.g. missing `https://`)",
1339         url::ParseError::EmptyHost => "URL host is empty",
1340         url::ParseError::InvalidPort => "URL port is invalid",
1341         url::ParseError::InvalidIpv4Address | url::ParseError::InvalidIpv6Address => {
1342             "URL host is not a valid IP address"
1343         }
1344         url::ParseError::InvalidDomainCharacter => "URL host contains an invalid character",
1345         url::ParseError::Overflow => "URL exceeds the maximum length",
1346         _ => "invalid URL",
1347     }
1348 }
