1350 /// Maps a [`GitHubRepositoryParseError`] to a specific, static diagnostic
1351 /// reason for [`GraphError::UnsafeGitRemote`], rather than discarding it
1352 /// behind one generic message for every distinct parse failure.
1353 fn github_repository_parse_error_reason(error: &GitHubRepositoryParseError) -> &'static str {
1354     match error {
1355         GitHubRepositoryParseError::MissingSeparator { .. } => "GitHub remote path must be in owner/repo form",
1356         GitHubRepositoryParseError::TooManyParts { .. } => "GitHub remote path has more than one `/`",
1357         GitHubRepositoryParseError::InvalidOwner { .. } => "GitHub owner name is invalid",
1358         GitHubRepositoryParseError::InvalidRepo { .. } => "GitHub repository name is invalid",
1359         #[allow(unreachable_patterns)]
1360         _ => "GitHub owner or repository name is invalid",
1361     }
1362 }
