1364 fn canonical_registry_binding(registry: &str, raw: &str) -> Result<RegistryBindingV1, GraphError> {
1365     let parsed = url::Url::parse(raw).map_err(|error| GraphError::UnsafeRegistryBinding {
1366         registry: registry.to_string(),
1367         reason: url_parse_error_reason(error),
1368     })?;
1369     if parsed.cannot_be_a_base() || parsed.host_str().is_none() {
1370         return Err(GraphError::UnsafeRegistryBinding {
1371             registry: registry.to_string(),
1372             reason: "URL must have an authority",
1373         });
1374     }
1375     if !matches!(parsed.scheme(), "http" | "https") {
1376         return Err(GraphError::UnsafeRegistryBinding {
1377             registry: registry.to_string(),
1378             reason: "URL scheme must be http or https",
1379         });
1380     }
1381     if !parsed.username().is_empty() || parsed.password().is_some() {
1382         return Err(GraphError::UnsafeRegistryBinding {
1383             registry: registry.to_string(),
1384             reason: "userinfo is forbidden",
1385         });
1386     }
1387     if parsed.query().is_some() {
1388         return Err(GraphError::UnsafeRegistryBinding {
1389             registry: registry.to_string(),
1390             reason: "query string is forbidden",
1391         });
1392     }
1393     if parsed.fragment().is_some() {
1394         return Err(GraphError::UnsafeRegistryBinding {
1395             registry: registry.to_string(),
1396             reason: "fragment is forbidden",
1397         });
1398     }
1399     Ok(RegistryBindingV1 {
1400         scheme: parsed.scheme().to_ascii_lowercase(),
1401         host: parsed.host_str().expect("validated authority").to_ascii_lowercase(),
1402         effective_port: parsed.port_or_known_default(),
1403         path: parsed.path().to_string(),
1404     })
1405 }
