1407 fn prepared_git_remote(root: &Path, runner: &dyn CommandRunner) -> Result<PreparedGitRemote, GraphError> {
1408     let output = runner.run("git", &["remote", "get-url", "--push", "origin"], root)?;
1409     if output.exit_code != Some(0) {
1410         return Err(GraphError::UnsafeGitRemote {
1411             reason: "origin must have a push URL",
1412         });
1413     }
1414     canonical_git_remote(output.stdout.trim())
1415 }
