1417 fn canonical_git_remote(raw: &str) -> Result<PreparedGitRemote, GraphError> {
1418     let ssh_url = if raw.starts_with("git@") && !raw.contains("//") {
1419         let (host, path) =
1420             raw.strip_prefix("git@")
1421                 .and_then(|value| value.split_once(':'))
1422                 .ok_or(GraphError::UnsafeGitRemote {
1423                     reason: "invalid SSH remote syntax",
1424                 })?;
1425         format!("ssh://git@{host}/{path}")
1426     } else {
1427         raw.to_string()
1428     };
1429     let parsed = url::Url::parse(&ssh_url).map_err(|error| GraphError::UnsafeGitRemote {
1430         reason: url_parse_error_reason(error),
1431     })?;
1432     if parsed.cannot_be_a_base() || parsed.host_str().is_none() {
1433         return Err(GraphError::UnsafeGitRemote {
1434             reason: "URL must have an authority",
1435         });
1436     }
1437     if !matches!(parsed.scheme(), "https" | "ssh") {
1438         return Err(GraphError::UnsafeGitRemote {
1439             reason: "URL scheme must be HTTPS or SSH",
1440         });
1441     }
1442     if parsed.password().is_some() || parsed.query().is_some() || parsed.fragment().is_some() {
1443         return Err(GraphError::UnsafeGitRemote {
1444             reason: "credentials, query strings, and fragments are forbidden",
1445         });
1446     }
1447     if parsed.scheme() == "https" && !parsed.username().is_empty() {
1448         return Err(GraphError::UnsafeGitRemote {
1449             reason: "HTTPS userinfo is forbidden",
1450         });
1451     }
1452     if parsed.scheme() == "ssh" && parsed.username() != "git" {
1453         return Err(GraphError::UnsafeGitRemote {
1454             reason: "SSH remotes must use the git account",
1455         });
1456     }
1457     let host = parsed.host_str().expect("validated authority").to_ascii_lowercase();
1458     let mut components = parsed.path_segments().ok_or(GraphError::UnsafeGitRemote {
1459         reason: "remote path is invalid",
1460     })?;
1461     let owner = components
1462         .next()
1463         .filter(|value| !value.is_empty())
1464         .ok_or(GraphError::UnsafeGitRemote {
1465             reason: "remote path must name an owner and repository",
1466         })?;
1467     let repository = components
1468         .next()
1469         .filter(|value| !value.is_empty())
1470         .ok_or(GraphError::UnsafeGitRemote {
1471             reason: "remote path must name an owner and repository",
1472         })?;
1473     if components.next().is_some() || owner == "." || owner == ".." || repository == "." || repository == ".." {
1474         return Err(GraphError::UnsafeGitRemote {
1475             reason: "remote path must contain exactly an owner and repository",
1476         });
1477     }
1478     let repository = repository.strip_suffix(".git").unwrap_or(repository);
1479     if repository.is_empty() {
1480         return Err(GraphError::UnsafeGitRemote {
1481             reason: "repository name is empty",
1482         });
1483     }
1484     let port = parsed.port_or_known_default();
1485     let port_text = match (parsed.scheme(), port) {
1486         ("https", Some(443)) | ("ssh", Some(22)) | (_, None) => String::new(),
1487         (_, Some(port)) => format!(":{port}"),
1488     };
1489     let endpoint = match parsed.scheme() {
1490         "https" => format!("https://{host}{port_text}/{owner}/{repository}.git"),
1491         "ssh" => format!("ssh://git@{host}{port_text}/{owner}/{repository}.git"),
1492         _ => unreachable!("scheme checked above"),
1493     };
1494     let mut transcript = CanonicalTranscript::semantic_input_v1();
1495     transcript.push_str("gitRemote.scheme", parsed.scheme());
1496     transcript.push_str("gitRemote.host", &host);
1497     transcript.push_str(
1498         "gitRemote.port",
1499         &port.map_or_else(String::new, |port| port.to_string()),
1500     );
1501     transcript.push_str("gitRemote.owner", owner);
1502     transcript.push_str("gitRemote.repository", repository);
1503     let github_repository = if host == "github.com" {
1504         Some(
1505             GitHubRepository::parse(&format!("{owner}/{repository}")).map_err(|error| GraphError::UnsafeGitRemote {
1506                 reason: github_repository_parse_error_reason(&error),
1507             })?,
1508         )
1509     } else {
1510         None
1511     };
1512     Ok(PreparedGitRemote {
1513         endpoint,
1514         identity: SemanticInputDigest::from_transcript(&transcript),
1515         github_repository,
1516     })
1517 }
