1714     /// Starts execution for exactly the roster authorized by `intent`.
1715     pub fn pending(intent: &ReleaseIntentV1) -> Self {
1716         Self {
1717             schema_version: Self::SCHEMA_VERSION,
1718             intent_digest: intent.digest.clone(),
1719             operations: intent
1720                 .operations
1721                 .iter()
1722                 .map(|operation| (operation.id.clone(), OperationState::Pending))
1723                 .collect(),
