1731     /// Validates that this state belongs to this exact intent and operation roster.
1732     ///
1733     /// Resume and reconciliation must call this before treating any state as
1734     /// evidence or before making a remote/VCS mutation.
1735     pub fn validate_for_intent(&self, intent: &ReleaseIntentV1) -> Result<(), ReleaseStateError> {
1736         if self.schema_version != Self::SCHEMA_VERSION {
1737             return Err(ReleaseStateError::UnsupportedSchema {
1738                 found: self.schema_version,
1739             });
1740         }
1741         if self.intent_digest != intent.digest {
1742             return Err(ReleaseStateError::MismatchedIntent);
1743         }
1744         let expected: BTreeSet<_> = intent.operations.iter().map(|operation| operation.id.clone()).collect();
1745         let actual: BTreeSet<_> = self.operations.keys().cloned().collect();
1746         if actual != expected {
1747             return Err(ReleaseStateError::MismatchedOperationRoster);
1748         }
1749         Ok(())
1750     }
