## cli_release
   1 //! Read-only durable release interfaces.
   2 //!
   3 //! Planning deliberately accepts only exact package identities. It never
   4 //! accepts an inline intent or searches for an authority file. Execution is
   5 //! intentionally not wired until the provider adapter can prove exact remote
   6 //! identities; exposing a permissive fallback here would recreate the legacy
   7 //! publish/tag bypass this command family replaces.
   8 
   9 use std::process::ExitCode;
  10 
  11 use callisto_graph::commands::{
  12     build_release_intent, derive_release_commit_decision, derive_selected_release_decision,
  13     execute_release_with_artifacts, reconcile_release_execution, validate_release_intent_with_state_directory,
  14     verify_artifact_manifest, ReleaseStateStore, VersionOptions,
  15 };
  16 use callisto_graph::locate::IgnoreWalkLocator;
  17 use callisto_model::{
  18     ApplyPermit, ArtifactManifestV1, ExecutionTrustProfileV1, ReleaseExecutionStateV1, ReleaseIntentV1,
  19     ReleasePackageId,
  20 };
  21 
  22 use crate::cli::{
  23     GlobalArgs, OutputFormat, ReleaseArgs, ReleaseExecuteArgs, ReleaseInspectArgs, ReleasePlanArgs,
  24     ReleaseReconcileArgs,
  25 };
  26 use crate::error::CliError;
  27 use crate::output::write_json;
  28 use crate::runner::CliCommandRunner;
  29 use crate::workspace::{load_workspace, select_inference};
  30 
  31 pub fn handle(args: ReleaseArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
  32     match args {
  33         ReleaseArgs::Plan(args) => plan(args, global),
  34         ReleaseArgs::Inspect(args) => inspect(args, global),
  35         ReleaseArgs::Reconcile(args) => reconcile(args, global),
  36         ReleaseArgs::Execute(args) => execute(args, global),
  37     }
  38 }
  39 
  40 fn plan(args: ReleasePlanArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
  41     if global.dry_run {
  42         return Err(CliError::Other(
  43             "release plan needs an output file; remove --dry-run because planning is already read-only".to_string(),
  44         ));
  45     }
  46     let runner = CliCommandRunner;
  47     let workspace = load_workspace(global, &runner)?;
  48     let decision = match args.from_release_commit.as_deref() {
  49         Some(raw) => {
  50             let commit = callisto_model::CommitSha::parse(raw)
  51                 .map_err(|error| CliError::Other(format!("invalid merged release commit `{raw}`: {error}")))?;
  52             let decision_path = args
  53                 .decision
  54                 .as_deref()
  55                 .expect("clap requires --decision alongside --from-release-commit");
  56             derive_release_commit_decision(&workspace, &commit, decision_path)?
  57         }
  58         None => {
  59             let selections = args
  60                 .packages
  61                 .iter()
  62                 .map(|raw| {
  63                     ReleasePackageId::parse(raw).map_err(|error| {
  64                         CliError::Other(format!(
  65                             "invalid release package `{raw}`: {error}; use an exact ecosystem-qualified identity such as cargo/callisto-cli"
  66                         ))
  67                     })
  68                 })
  69                 .collect::<Result<Vec<_>, _>>()?;
  70             let inference = select_inference();
  71             let version_plan =
  72                 callisto_graph::commands::plan_version(&workspace, &inference, &VersionOptions::default())?;
  73             derive_selected_release_decision(&workspace, &version_plan, &selections)?
  74         }
  75     };
  76     let locator = IgnoreWalkLocator::new(&workspace.root);
  77     let intent = build_release_intent(
  78         &workspace.root,
  79         &locator,
  80         &runner,
  81         &decision,
  82         ExecutionTrustProfileV1::GitCommit,
  83     )?;
  84     let permit = ApplyPermit::granted_unless_dry_run(global.dry_run)
  85         .expect("release plan rejects --dry-run before creating its explicit output");
  86     write_intent(&args.out, &intent, &permit)?;
  87     match global.format {
  88         OutputFormat::Json => write_json(&mut std::io::stdout(), &intent)?,
  89         OutputFormat::Text => println!("Wrote release intent {} to {}", intent.digest(), args.out.display()),
  90     }
  91     Ok(ExitCode::SUCCESS)
  92 }
  93 
  94 fn inspect(args: ReleaseInspectArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
  95     let value = read_json_file(&args.input)?;
  96     match global.format {
  97         OutputFormat::Json => write_json(&mut std::io::stdout(), &value)?,
  98         OutputFormat::Text => println!(
  99             "{}",
 100             serde_json::to_string_pretty(&value).expect("JSON value serializes")
 101         ),
 102     }
 103     Ok(ExitCode::SUCCESS)
 104 }
 105 
 106 fn reconcile(args: ReleaseReconcileArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
 107     let intent = read_intent(&args.intent)?;
 108     let state = match args.state {
 109         Some(path) => ReleaseStateStore::new(path).load(&intent)?,
 110         None => None,
 111     }
 112     .unwrap_or_else(|| ReleaseExecutionStateV1::pending(&intent));
 113     let report = reconcile_release_execution(&intent, &state)?;
 114     match global.format {
 115         OutputFormat::Json => write_json(&mut std::io::stdout(), report.eligible())?,
 116         OutputFormat::Text => {
 117             for operation in report.eligible() {
 118                 println!("eligible: {operation:?}");
 119             }
 120         }
 121     }
 122     Ok(ExitCode::SUCCESS)
 123 }
