1744         let expected: BTreeSet<_> = intent.operations.iter().map(|operation| operation.id.clone()).collect();
1745         let actual: BTreeSet<_> = self.operations.keys().cloned().collect();
1746         if actual != expected {
1747             return Err(ReleaseStateError::MismatchedOperationRoster);
1748         }
1749         Ok(())
1750     }
