1757     fn from_wire(wire: ReleaseExecutionStateV1Wire) -> Result<Self, ReleaseStateError> {
1758         if wire.schema_version != Self::SCHEMA_VERSION {
1759             return Err(ReleaseStateError::UnsupportedSchema {
1760                 found: wire.schema_version,
1761             });
1762         }
1763         let mut operations = BTreeMap::new();
1764         for entry in wire.operations {
1765             if operations.insert(entry.operation.clone(), entry.state).is_some() {
1766                 return Err(ReleaseStateError::DuplicateOperation {
1767                     id: Box::new(entry.operation),
1768                 });
1769             }
1770         }
1771         Ok(Self {
1772             schema_version: wire.schema_version,
1773             intent_digest: wire.intent_digest,
1774             operations,
1775         })
1776     }
