1795     pub fn mark_terminal(
1796         &mut self,
1797         id: &ReleaseOperationId,
1798         outcome: OperationOutcome,
1799     ) -> Result<(), ReleaseStateError> {
1800         let state = self
1801             .operations
1802             .get_mut(id)
1803             .ok_or_else(|| ReleaseStateError::UnknownOperation {
1804                 id: Box::new(id.clone()),
1805             })?;
1806         if *state != OperationState::Attempting {
1807             return Err(ReleaseStateError::InvalidTransition {
1808                 id: Box::new(id.clone()),
1809                 from: *state,
1810             });
1811         }
1812         *state = match outcome {
1813             OperationOutcome::Published => OperationState::Published,
1814             OperationOutcome::AlreadySatisfied => OperationState::AlreadySatisfied,
1815             OperationOutcome::Failed => OperationState::Failed,
1816             OperationOutcome::Blocked { reason } => OperationState::Blocked { reason },
