## release_store
   1 //! Narrow, explicit-path persistence for durable release execution state.
   2 //!
   3 //! The store owns no release policy and does not derive paths from mutable
   4 //! workspace configuration. Callers must supply the state path deliberately.
   5 
   6 use std::path::{Path, PathBuf};
   7 
   8 use callisto_model::{atomic::atomic_write, ApplyPermit, ReleaseExecutionStateV1, ReleaseIntentV1};
   9 
  10 use crate::GraphError;
  11 
  12 /// The only write seam used by [`ReleaseStateStore`]. Production writes use
  13 /// Callisto's crash-safe atomic replacement primitive; tests can inject a
  14 /// pre-rename failure without weakening that production path.
  15 pub trait ReleaseStateWriter {
  16     fn write(&self, path: &Path, content: &str, permit: &ApplyPermit) -> std::io::Result<()>;
  17 }
  18 
  19 /// Production state writer backed by [`callisto_model::atomic::atomic_write`].
  20 #[derive(Clone, Copy, Debug, Default)]
  21 pub struct AtomicReleaseStateWriter;
  22 
  23 impl ReleaseStateWriter for AtomicReleaseStateWriter {
  24     fn write(&self, path: &Path, content: &str, permit: &ApplyPermit) -> std::io::Result<()> {
  25         atomic_write(path, content, permit)
  26     }
  27 }
  28 
  29 /// Durable state store at one caller-chosen path.
  30 #[derive(Debug)]
  31 pub struct ReleaseStateStore<W = AtomicReleaseStateWriter> {
  32     path: PathBuf,
  33     writer: W,
  34 }
  35 
  36 impl ReleaseStateStore {
  37     /// Creates a production store at an explicit path.
  38     pub fn new(path: impl Into<PathBuf>) -> Self {
  39         Self::with_writer(path, AtomicReleaseStateWriter)
  40     }
  41 
  42     /// Creates a local state store outside the checkout, keyed by the exact
  43     /// durable intent. CI should use [`Self::new`] with an explicit path so a
  44     /// workflow artifact can hand state between jobs without using a cache.
  45     pub fn default_for(canonical_root: &Path, intent: &ReleaseIntentV1) -> Result<Self, GraphError> {
  46         let root = dunce::canonicalize(canonical_root).map_err(|error| GraphError::ReleaseStateRead {
  47             path: canonical_root.to_path_buf(),
  48             message: error.to_string(),
  49         })?;
  50         let mut transcript = callisto_model::CanonicalTranscript::semantic_input_v1();
  51         transcript.push_str("workspace-root", &root.to_string_lossy());
  52         let root_key = callisto_model::SemanticInputDigest::from_transcript(&transcript);
  53         let base = callisto_vcs::release_lock::platform_state_directory()?;
  54         Ok(Self::new(
  55             base.join("callisto")
  56                 .join("release-state")
  57                 .join(root_key.as_str())
  58                 .join(format!("{}.json", intent.digest().as_str())),
  59         ))
  60     }
  61 }
  62 
  63 impl<W> ReleaseStateStore<W>
  64 where
  65     W: ReleaseStateWriter,
  66 {
  67     /// Creates a store with a narrow writer seam, primarily for deterministic
  68     /// failure tests. The path remains explicit and is never config-derived.
  69     pub fn with_writer(path: impl Into<PathBuf>, writer: W) -> Self {
  70         Self {
  71             path: path.into(),
  72             writer,
  73         }
  74     }
  75 
  76     /// Returns the caller-chosen durable state location.
  77     pub fn path(&self) -> &Path {
  78         &self.path
  79     }
  80 
  81     /// Loads state if it exists and rejects any state not exactly bound to
  82     /// `intent`. A missing file is not evidence of a completed release.
  83     pub fn load(&self, intent: &ReleaseIntentV1) -> Result<Option<ReleaseExecutionStateV1>, GraphError> {
  84         let content = match std::fs::read_to_string(&self.path) {
  85             Ok(content) => content,
  86             Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(None),
  87             Err(error) => {
  88                 return Err(GraphError::ReleaseStateRead {
  89                     path: self.path.clone(),
  90                     message: error.to_string(),
  91                 });
  92             }
  93         };
  94         let state: ReleaseExecutionStateV1 =
  95             serde_json::from_str(&content).map_err(|error| GraphError::ReleaseStateDecode {
  96                 path: self.path.clone(),
  97                 message: error.to_string(),
  98             })?;
  99         state
 100             .validate_for_intent(intent)
 101             .map_err(|source| GraphError::ReleaseExecutionState { source })?;
 102         Ok(Some(state))
 103     }
 104 
 105     /// Loads existing state or atomically writes the exact pending roster.
 106     pub fn load_or_initialize(
 107         &self,
 108         intent: &ReleaseIntentV1,
 109         permit: &ApplyPermit,
 110     ) -> Result<ReleaseExecutionStateV1, GraphError> {
 111         if let Some(state) = self.load(intent)? {
 112             return Ok(state);
 113         }
 114         let state = ReleaseExecutionStateV1::pending(intent);
 115         self.save(intent, &state, permit)?;
 116         Ok(state)
 117     }
 118 
 119     /// Atomically persists only state proven to belong to `intent`.
 120     pub fn save(
 121         &self,
 122         intent: &ReleaseIntentV1,
 123         state: &ReleaseExecutionStateV1,
 124         permit: &ApplyPermit,
 125     ) -> Result<(), GraphError> {
 126         state
 127             .validate_for_intent(intent)
 128             .map_err(|source| GraphError::ReleaseExecutionState { source })?;
 129         let content = serde_json::to_string_pretty(state).expect("release state serialization is infallible") + "\n";
 130         self.writer
 131             .write(&self.path, &content, permit)
 132             .map_err(|error| GraphError::ReleaseStateWrite {
 133                 path: self.path.clone(),
 134                 message: error.to_string(),
 135             })
 136     }
 137 }
